package markdown

import (
	"fmt"
	"strings"
)

// Refactoring notes:
//
// The original implementation walked the input one byte at a time with a
// shared position index, mixed four unrelated states (header level, a
// "header already seen" flag, a list counter and a list-opened flag) into a
// single loop, and pre-rewrote the whole document with strings.Replace
// before parsing. It also relied on quirks such as "lists only work if the
// document contains a newline" and "only the first __/_ pair in the whole
// document is formatted".
//
// The rewrite parses the input line by line, which matches how Markdown is
// actually structured:
//   - a line starting with 1-6 '#' characters is a heading (7 or more is
//     not valid Markdown and falls back to a paragraph),
//   - a line starting with "* " is an unordered list item,
//   - any other line is a paragraph.
//
// Consecutive list items are grouped into one <ul>, and emphasis markers
// are formatted per line instead of per document. Each rule now lives in
// its own small helper, so the main loop only expresses the document
// structure.

// Render translates markdown to HTML.
func Render(input string) string {
	var b strings.Builder
	inList := false

	for _, line := range strings.Split(input, "\n") {
		if level, text, ok := parseHeading(line); ok {
			closeList(&b, &inList)
			if level > 6 {
				// Markdown only defines h1-h6; a run of 7+ '#' is
				// rendered as a literal paragraph.
				fmt.Fprintf(&b, "<p>%s</p>", formatEmphasis(line))
			} else {
				fmt.Fprintf(&b, "<h%d>%s</h%d>", level, formatEmphasis(text), level)
			}
			continue
		}

		if item, ok := parseListItem(line); ok {
			if !inList {
				b.WriteString("<ul>")
				inList = true
			}
			fmt.Fprintf(&b, "<li>%s</li>", formatEmphasis(item))
			continue
		}

		closeList(&b, &inList)
		fmt.Fprintf(&b, "<p>%s</p>", formatEmphasis(line))
	}

	closeList(&b, &inList)
	return b.String()
}

// closeList closes an open <ul> element, if any.
func closeList(b *strings.Builder, inList *bool) {
	if *inList {
		b.WriteString("</ul>")
		*inList = false
	}
}

// parseHeading reports whether line is a heading. If so, it returns the
// heading level (number of leading '#') and the heading text, with the
// separating space removed.
func parseHeading(line string) (level int, text string, ok bool) {
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level == 0 {
		return 0, "", false
	}
	text = line[level:]
	if strings.HasPrefix(text, " ") {
		text = text[1:]
	}
	return level, text, true
}

// parseListItem reports whether line is an unordered list item and, if so,
// returns the item text.
func parseListItem(line string) (string, bool) {
	if !strings.HasPrefix(line, "* ") {
		return "", false
	}
	return line[2:], true
}

// formatEmphasis translates the first "__bold__" and "_italic_" markers in
// text to <strong> and <em> tags.
func formatEmphasis(text string) string {
	text = strings.Replace(text, "__", "<strong>", 1)
	text = strings.Replace(text, "__", "</strong>", 1)
	text = strings.Replace(text, "_", "<em>", 1)
	text = strings.Replace(text, "_", "</em>", 1)
	return text
}

